-- Lista mlek do ręcznego przeglądu (tylko odczyt): zwykłe mleko w ml, poza grupami mleka, bez wcześniejszej decyzji.
-- Powód: nazwa nie mówi, czy to UHT czy świeże (albo brak zawartości tłuszczu). Warianty smakowe, barista, proteinowe,
-- zagęszczone, w proszku i roślinne są pominięte - to inne produkty.
-- Wynik: /sql/mleko-do-przegladu.csv (średniki, UTF-8). Uzupełnij kolumnę "rodzaj": UHT / świeże / pomiń;
-- w razie potrzeby popraw "tluszcz" (np. 3,2) i "laktoza" (z laktozą / bez laktozy). Potem: scripts/mleko/przeglad-mleka.mjs.
\copy (SELECT p.id AS produkt_id, string_agg(DISTINCT s.slug, ', ') AS sieci, p.canonical_name AS nazwa, round(p.quantity_value)::int AS ml, p.ean, min(coalesce(o.regular_price, o.promo_price)) AS cena, replace(substring(replace(p.canonical_name, ',', '.') FROM '([0-9]+(?:\.[0-9]+)?)\s*%'), '.', ',') AS tluszcz, CASE WHEN public.norm_text(p.canonical_name) ~ 'bez lakt|bezlakt|bez lektozy' THEN 'bez laktozy' ELSE 'z laktozą' END AS laktoza, CASE WHEN public.norm_text(p.canonical_name) ~ '\muht\M' THEN 'UHT' WHEN public.norm_text(p.canonical_name) ~ 'swiez' THEN 'świeże' ELSE '' END AS rodzaj, '' AS uwagi FROM public.products p JOIN public.comparison_groups g ON g.id = p.comparison_group_id LEFT JOIN public.store_offers o ON o.product_id = p.id LEFT JOIN public.stores s ON s.id = o.store_id WHERE g.group_key NOT LIKE 'milk:%' AND coalesce(p.classification_source, '') <> 'reviewed' AND p.quantity_unit = 'ml' AND public.norm_text(p.canonical_name) ~ '\mmleko\M' AND public.norm_text(p.canonical_name) !~ '(kokos|soj|owsian|migdal|czekolad|wanili|w proszku|skondens|kondens|zageszcz|fermentowan|\mnie mleko\M|roslinn|smakow|o smaku|truskawk|kaka|banan|kawow|protein|barista)' AND NOT (public.norm_text(p.canonical_name) ~ 'smak' AND public.norm_text(p.canonical_name) !~ 'mazurski smak') AND NOT EXISTS (SELECT 1 FROM public.catalog_reviews r WHERE r.product_id = p.id AND r.topic = 'milk') GROUP BY p.id ORDER BY 2, 3) TO '/sql/mleko-do-przegladu.csv' WITH (FORMAT csv, HEADER true, DELIMITER ';', ENCODING 'UTF8')
